insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-4405')::uuid, md5('building-grosser-burstah-25-20457')::uuid, '4405', 'bueroflaeche-in-bester-innenstadtlage-4405', 'Bürofläche in bester Innenstadtlage', 'Das Büro- und Geschäftshaus befindet sich in bester Citylage in unmittelbarer Nähe zu Rathausmarkt und Mönckebergstraße. Zahlreiche Restaurants, Cafes und alle Geschäfte des …', 'Das Büro- und Geschäftshaus befindet sich in bester Citylage in unmittelbarer Nähe zu Rathausmarkt und Mönckebergstraße. Zahlreiche Restaurants, Cafes und alle Geschäfte des täglichen Bedarfs befinden sich im direkten Umfeld. Die U- und S-Bahnstationen Rödingsmarkt, Stadthausbrücke und Rathausmarkt sind nach wenigen Fußminuten erreicht. Über die modernisierten Eingangsbereiche mit Personenfahrstühlen sind die jeweiligen Etagen zu erreichen. Die hellen und funktionalen Mieteinheiten können in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Die Bilder stammen aus einer modernisierten Einheit im Gebäude. PKW-Stellplätze können in der Umgebung angemietet werden.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-4405-1')::uuid, md5('property-4405')::uuid, 'Mietfläche', 244, 23.5, null, 'filemaker', '4405-1') on conflict (id) do nothing;
