insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8669')::uuid, md5('building-willhoop-1-3-22453')::uuid, '8669', 'wirtschaftliche-bueroflaeche-in-flughafennaehe-8669', 'Wirtschaftliche Bürofläche in Flughafennähe', 'Das Büro- und Geschäftshaus befindet sich im Stadtteil Groß Borstel an der Grenze zu Niendorf nahe des Hamburger Flughafens und der Autobahn A7, Anschluss Schnelsen. Der …', 'Das Büro- und Geschäftshaus befindet sich im Stadtteil Groß Borstel an der Grenze zu Niendorf nahe des Hamburger Flughafens und der Autobahn A7, Anschluss Schnelsen. Der Hauptbahnhof ist in ca. 20 Autominuten erreicht und eine fußläufig schnell erreichte Bushaltestelle sichert außerdem eine gute Anbindung an den ÖPNV. Die Bürofläche im 1. OG erschließt sich über ein repräsentatives Foyer mit  zwei Personenaufzügen. Die Räumlichkeiten sind funktional und modern ausgestattet und verfügen u.a. über abgehängte Decken mit Raster-Einbauleuchten, Hohlraumboden für eine EDV-Verkabelung und separaten WC-Einheiten auf gleicher Ebene außerhalb der Fläche. Die Innenansichten sind beispielhaft gewählt. PKW-Stellplätze können sowohl vor dem Objekt als auch in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 141, 394, 'https://www.buerohamburg.de/objects/pdf/BHI_8669.pdf', null, 'filemaker', '8669') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-8669-1')::uuid, md5('property-8669')::uuid, 'Mietfläche', 256, 7.9, null, 'filemaker', '8669-1') on conflict (id) do nothing;
