insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23245')::uuid, md5('building-notkestrasse-13-15-22607')::uuid, '23245', 'ansprechender-buerokomplex-sunny-point-in-bahrenfeld-23245', 'Ansprechender Bürokomplex Sunny Point in Bahrenfeld', 'Der gepflegte Bürokomplex Sunny Point befindet sich in zentraler Lage des Hamburger Stadtteils Bahrenfeld. Der Altonaer Volkspark, die Trabrennbahn und das Elbe Einkaufszentrum …', 'Der gepflegte Bürokomplex Sunny Point befindet sich in zentraler Lage des Hamburger Stadtteils Bahrenfeld. Der Altonaer Volkspark, die Trabrennbahn und das Elbe Einkaufszentrum mit zahlreichen Einkaufsmöglichkeiten und gastronomischen Angeboten sind fußläufig schnell erreicht. Eine Buslinie sichert den direkten Anschluss an den ÖPNV. Das Objekt wird barrierefrei über einen repräsentativen Eingangsbereich mit drei Personen- und Lastenaufzügen erschlossen. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Archiv- und Lagerflächen sowie ausreichend PKW-Stellplätze in der hauseigenen Tiefgarage können angemietet werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer anderen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 257, 819, 'https://www.buerohamburg.de/objects/pdf/BHI_23245.pdf', null, 'filemaker', '23245') on conflict (id) do nothing;
