insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-252')::uuid, md5('building-steinstrasse-25-20095')::uuid, '252', 'individuell-bueroflaeche-nahe-des-hauptbahnhofs-252', 'Individuell Bürofläche nahe des Hauptbahnhofs', 'Das denkmalgeschützte Büro- und Geschäftsgebäude befindet sich in zentraler Hamburger Innenstadtlage nur wenige Meter von der Mönckebergstraße entfernt. Das direkte Umfeld bietet …', 'Das denkmalgeschützte Büro- und Geschäftsgebäude befindet sich in zentraler Hamburger Innenstadtlage nur wenige Meter von der Mönckebergstraße entfernt. Das direkte Umfeld bietet gute Einkaufsmöglichkeiten und eine Vielzahl an Cafés und Restaurants. Sämtliche U- und S-Bahnanbindungen sind fußläufig über die Station Jungfernstieg und den nahegelegenen Hauptbahnhof zu erreichen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-252-1')::uuid, md5('property-252')::uuid, 'Mietfläche', 258, 22.5, null, 'filemaker', '252-1') on conflict (id) do nothing;
