insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21952')::uuid, md5('building-humboldtstrasse-51-55-22083')::uuid, '21952', 'funktionale-bueroflaeche-in-ruhiger-lage-21952', 'Funktionale Bürofläche in ruhiger Lage', 'Der gepflegte Gewerbehof befindet sich parallel zum Winterhuder Weg in einer ruhigen Seitenstraße unweit des Einkaufszentrum Hamburger Straße. Vielseitige Einkaufsmöglichkeiten …', 'Der gepflegte Gewerbehof befindet sich parallel zum Winterhuder Weg in einer ruhigen Seitenstraße unweit des Einkaufszentrum Hamburger Straße. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants prägen das direkte Umfeld. Die vakante Bürofläche befindet sich im Hochparterre und teilt sich in Einzel-, Kombi- und Großraumbüros auf. Die aktuelle Ausstattung umfasst u.a. Teppichbodenbelag sowie separate WC-Einheiten und eine Pantry. Die weitere Ausstattung und Aufteilung der Fläche erfolgt in Absprache mit dem zukünftigen Mieter. Das Gebäude verfügt außerdem über ausreichend Lagerflächen welche zusätzlich angemietet werden können. PKW-Stellplätze können am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_21952.pdf', null, 'filemaker', '21952') on conflict (id) do nothing;
