insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-2847')::uuid, md5('building-willy-brandt-strasse-57-20457')::uuid, '2847', 'moderne-buero-oder-ladenflaeche-direkt-am-nikolaifleet-2847', 'Moderne Büro- oder Ladenfläche direkt am Nikolaifleet', 'Das prägnante Bürogebäude befindet sich in verkehrsgünstiger Lage des südlichen Innenstadtkerns direkt am Nikolaifleet. Die Anbindung an den öffentlichen Nahverkehr ist durch die …', 'Das prägnante Bürogebäude befindet sich in verkehrsgünstiger Lage des südlichen Innenstadtkerns direkt am Nikolaifleet. Die Anbindung an den öffentlichen Nahverkehr ist durch die in wenigen Gehminuten erreichbaren Haltestellen Rathausmarkt, Meßberg und Rödingsmarkt gewährleistet. Das Umfeld ist durch zahlreiche Einkaufsmöglichkeiten, Cafés und Restaurants geprägt. Die hochmoderne Fläche besticht durch ihre effiziente Nutzung und eignet sich als Büro- und auch als Einzelhandelsfläche. Aufteilung und Ausstattung erfolgen in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['erdgeschoss', 'stellplaetze', 'wasserblick']::text[], 259, 544, 'https://www.buerohamburg.de/objects/pdf/BHI_2847.pdf', null, 'filemaker', '2847') on conflict (id) do nothing;
