insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-10919')::uuid, md5('building-gerhofstrasse-10-12-20354')::uuid, '10919', 'modernes-buerohaus-mit-dachterrasse-in-bester-innenstadtlage-10919', 'Modernes Bürohaus mit Dachterrasse in bester Innenstadtlage', 'Das moderne Wohn- und Geschäftsgebäude befindet sich in einer ruhigen Fußgängerzone unmittelbar am Gänsemarkt. Das attraktive Umfeld ist geprägt durch hochwertige Einzelhändler, …', 'Das moderne Wohn- und Geschäftsgebäude befindet sich in einer ruhigen Fußgängerzone unmittelbar am Gänsemarkt. Das attraktive Umfeld ist geprägt durch hochwertige Einzelhändler, alle Geschäfte des täglichen Bedarfs, sowie eine Vielzahl gastronomischer Angebote. Der Anschluss an das öffentliche Verkehrsnetz kann durch die nahe gelegene U- und S-Bahnstationen Jungfernstieg sowie Gänsemarkt als hervorragend bezeichnet werden. Zur Ausstattung der modernen Büroflächen zählen u. a. hochwertiger Teppichfußboden, bodentiefe Fenster, außenliegender elektrischer Sonnenschutz, eine Pantry, sowie getrennte WC-Einheiten. Ein besonderes Highlight ist die exklusiv zu nutzende Dachterrasse. PKW-Stellplätze können im nahegelegenen Parkhaus Hanse-Viertel angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_10919.pdf', null, 'filemaker', '10919') on conflict (id) do nothing;
