insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24226')::uuid, md5('building-weberstrasse-5-22083')::uuid, '24226', 'barmbek-effiziente-und-moderne-bueroflaeche-in-der-alstercity-24226', 'Barmbek: Effiziente und moderne Bürofläche in der AlsterCity', 'Das markante Bürogebäude befindet sich zwischen Osterbekkanal und Weidestraße im schönen Stadtteil Winterhude. Durch verschiedene Buslinien ist eine gute Anbindung an den ÖPNV …', 'Das markante Bürogebäude befindet sich zwischen Osterbekkanal und Weidestraße im schönen Stadtteil Winterhude. Durch verschiedene Buslinien ist eine gute Anbindung an den ÖPNV gegeben. Die Alster-City mit ihrer hauseigenen Shoppingmall befindet sich mit auf diesem großzügigen Areal. Die Büroflächen können in Absprache mit dem zukünftigen Mieter aufgeteilt werden, der Mietpreis richtet sich nach den individuellen Ausstattungswünschen. PKW-Stellplätze können zusätzlich angemietet werden. Die beigefügten Bilder sind beispielhaft ausgewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 260, 520, 'https://www.buerohamburg.de/objects/pdf/BHI_24226.pdf', null, 'filemaker', '24226') on conflict (id) do nothing;
