insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24291')::uuid, md5('building-karnapp-25-21079')::uuid, '24291', 'flexibel-gestaltbare-bueroflaeche-im-harburger-binnenhafen-24291', 'Flexibel gestaltbare Bürofläche im Harburger Binnenhafen', 'Der architektonisch sehr ansprechende Channel Tower befindet sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie …', 'Der architektonisch sehr ansprechende Channel Tower befindet sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie die Harburger Altstadt. Das Objekt verfügt über einen repräsentativen, lichtdurchfluteten Eingangsbereich. Die geplante Ausstattung der Bürofläche umfasst unter anderem eine Grundbeleuchtung, einen hochwertigen Bodenbelag, innenliegenden Blendschutz, ein EDV Raum,  eine funktionale Teeküche sowie separate sanitäre Anlagen. Die weitere Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenbilder sind beispielhaft gewählt und stammen aus einer bereits ausgebauten Mietfläche im Objekt. PKW-Stellplätze können nach Absprache auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 260, 1600, 'https://www.buerohamburg.de/objects/pdf/BHI_24291.pdf', null, 'filemaker', '24291') on conflict (id) do nothing;
