insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8942')::uuid, md5('building-amsinckstrasse-57-61-20097')::uuid, '8942', 'architektur-highlight-in-der-city-sued-mit-balkon-8942', 'Architektur-Highlight in der City-Süd mit Balkon', 'Das markante Bürogebäude befindet sich in zentraler Lage in der City-Süd zwischen Nagelsweg und Amsinckstraße. Die Autobahnen A1 und A24 sowie die Hamburger Innenstadt erreichen …', 'Das markante Bürogebäude befindet sich in zentraler Lage in der City-Süd zwischen Nagelsweg und Amsinckstraße. Die Autobahnen A1 und A24 sowie die Hamburger Innenstadt erreichen Sie in wenigen Fahrminuten. Die Anbindung an den öffentlichen Nahverkehr ist sehr gut, die Die S-Bahn-Station Hammerbrook in wenigen Gehminuten erreicht. Im unmittelbaren Umfeld befinden sich diverse Cafés und Restaurants. Die ca. 263 qm erstrecken sich über drei Etagen, welche mit einer internen Wendeltreppe miteinander verbunden sind. Zur Ausstattung der Flächen zählen u.a. bodentiefe Fensterelemente und Hohl- bzw. Doppelböden für die EDV-Verkabelung. Eine doppelte Glasfassade, außenliegender Sonnenschutz und glatte Betondecken und Wände sorgen für optimale Arbeitsbedingungen. Diese Bilder sind beispielhaft gewählt. PKW-Stellplätze können bei Bedarf am Objekt gemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 263, 10393, 'https://www.buerohamburg.de/objects/pdf/BHI_8942.pdf', null, 'filemaker', '8942') on conflict (id) do nothing;
