insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25342')::uuid, md5('building-luruper-chaussee-125-22761')::uuid, '25342', 'moderne-bueroflaeche-im-historischen-kavallerie-quartier-25342', 'Moderne Bürofläche im historischen Kavallerie-Quartier', 'In einem etablierten Business-Quartier auf dem Gelände der ehemaligen Kavallerieschule in Hamburg-Bahrenfeld steht eine attraktive Bürofläche zur Vermietung. Die hellen …', 'In einem etablierten Business-Quartier auf dem Gelände der ehemaligen Kavallerieschule in Hamburg-Bahrenfeld steht eine attraktive Bürofläche zur Vermietung. Die hellen Räumlichkeiten überzeugen durch hohe Decken, eine freundliche Arbeitsatmosphäre und teilweise hochwertiges Fischgrätparkett, das den besonderen Altbaucharme unterstreicht. Zur Ausstattung gehören zudem CAT-7-Verkabelung, eine Teeküche sowie separate WC-Einheiten. Die Aufteilung und weitere Ausstattungsdetails können in Abstimmung mit dem zukünftigen Mieter individuell gestaltet werden. PKW-Stellplätze stehen auf dem Gewerbehof zur Anmietung zur Verfügung.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25342-1')::uuid, md5('property-25342')::uuid, 'Mietfläche', 265, 14.5, null, 'filemaker', '25342-1') on conflict (id) do nothing;
