insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21654')::uuid, md5('building-theodorstrasse-42-90-22761')::uuid, '21654', 'bueroneubau-im-traditionellen-westend-village-21654', 'Büroneubau im traditionellen Westend-Village', 'Das New Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten. Das Areal bietet zahlreiche Serviceeinrichtungen wie …', 'Das New Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten. Das Areal bietet zahlreiche Serviceeinrichtungen wie Swimmingpool, Waschcenter und eine ansprechende Gartenanlage. Der traditionelle Bestand des Westend-Village wurde durch moderne Neubauten erweitert in dem sich diese hochwertige Bürofläche befindet. Diese verfügt u.a. über einen Holzfußboden, Sichtbeton, Kabeltrassen, getrennte WC-Einheiten sowie eine großzügige Teeküche. Die Innenansichten stammen aus einer ähnlichen Fläche im Gebäude. PKW-Stellplätze können auf Anfrage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 196, 4300, 'https://www.buerohamburg.de/objects/pdf/BHI_21654.pdf', null, 'filemaker', '21654') on conflict (id) do nothing;
