insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24884')::uuid, md5('building-christoph-probst-weg-1-4-20251')::uuid, '24884', 'modernes-buero-im-quartier-am-zeughaus-24884', 'Modernes Büro im Quartier am Zeughaus', 'Der moderne Büroneubau im historischen Ambiente befindet sich im westlichen Eppendorf nahe der Universitätsklinik. Flughafennähe, schnelle Anbindung an die Autobahnen sowie eine …', 'Der moderne Büroneubau im historischen Ambiente befindet sich im westlichen Eppendorf nahe der Universitätsklinik. Flughafennähe, schnelle Anbindung an die Autobahnen sowie eine Bushaltestelle direkt vor dem Objekt stellen eine gute Verkehrsanbindung dar. Gastronomische Einrichtungen sind fußläufig bequem in der Mittagspause zu erreichen. Zur exzellenten Ausstattung zählt u.a. die flexible Aufteilung sowohl in Einzel- als auch Team- und Gruppenbüros, sehr hochwertige Materialien, ein Hohlraumboden, eine computergerechte Beleuchtung, ein außen liegender Sonnenschutz sowie eine komplett ausgestattete Teeküche. Der Mietpreis hängt von den individuellen Umbauwünschen des zukünftigen Mieters ab. Diese Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 267, 734, 'https://www.buerohamburg.de/objects/pdf/BHI_24884.pdf', null, 'filemaker', '24884') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24884-1')::uuid, md5('property-24884')::uuid, 'Mietfläche', 267, 18.5, null, 'filemaker', '24884-1') on conflict (id) do nothing;
