insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-10843')::uuid, md5('building-heidenkampsweg-51-57-20097')::uuid, '10843', 'city-sued-showroom-in-zentraler-lage-zwischen-elbbruecken-und-innenstadt-10843', 'City Süd: Showroom in zentraler Lage zwischen Elbbrücken und Innenstadt', 'Das imposante Büro- und Geschäftsgebäude befindet sich im Herzen der City-Süd mit guter Anbindung an die Hamburger Innenstadt, den Hauptbahnhof und die Autobahn. Die …', 'Das imposante Büro- und Geschäftsgebäude befindet sich im Herzen der City-Süd mit guter Anbindung an die Hamburger Innenstadt, den Hauptbahnhof und die Autobahn. Die S-Bahnhaltestelle Hammerbrook ist fußläufig schnell erreicht und sichert den Anschluss an den ÖPNV. Gute Einkaufsmöglichkeiten und diverse Cafés und Restaurants beleben das direkte Umfeld. Die großzügige Fläche ist aktuell mit Teppichboden, Küchenzeile, Beleuchtungssystem und separaten WC-Einheiten ausgestattet und teilt sich aktuell in zwei Räume. Diverse Nutzungskonzepte sind vorstellbar. Pkw-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'erdgeschoss']::text[], 150, 1487, 'https://www.buerohamburg.de/objects/pdf/BHI_10843.pdf', null, 'filemaker', '10843') on conflict (id) do nothing;
