insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25485')::uuid, md5('building-albert-einstein-ring-11-15-22761')::uuid, '25485', 'bahrenfeld-bueroflaeche-nahe-der-autobahn-a7-25485', 'Bahrenfeld: Bürofläche nahe der Autobahn A7', 'Diese Solitärimmobilie befindet sich in gut sichtbare Lage unmittelbar an der Trabrennbahn Bahrenfeld und der gleichnamigen Autobahnauffahrt der A7. Im nahen Umfeld befinden sich …', 'Diese Solitärimmobilie befindet sich in gut sichtbare Lage unmittelbar an der Trabrennbahn Bahrenfeld und der gleichnamigen Autobahnauffahrt der A7. Im nahen Umfeld befinden sich diverse Einkaufsmöglichkeiten und Restaurants. Die Bürofläche ist über repräsentativ gestaltete Foyers erschlossen. Die Bürofläche ist derzeitig ausgebaut kann aber in Absprache mit dem zukünftigen Mieter neu aufgeteilt werden. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder stammen aus einer modernisierten Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 187, 462, 'https://www.buerohamburg.de/objects/pdf/BHI_25485.pdf', null, 'filemaker', '25485') on conflict (id) do nothing;
