insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24905')::uuid, md5('building-neuer-wall-63-20354')::uuid, '24905', 'bueroflaeche-in-exklusiver-lage-am-neuen-wall-24905', 'Bürofläche in exklusiver Lage am Neuen Wall', 'Das moderne Bürogebäude befindet sich in bester Innenstadtlage nahe der Binnenalster und dem Rathausmarkt. Der Neue Wall zählt zu den exklusivsten Lagen der Hamburger City. …', 'Das moderne Bürogebäude befindet sich in bester Innenstadtlage nahe der Binnenalster und dem Rathausmarkt. Der Neue Wall zählt zu den exklusivsten Lagen der Hamburger City. Zahlreiche Restaurants und Cafés, hochwertige Einzelhändler und eine sehr gute Anbindung an das öffentliche Verkehrsnetz unterstreichen die Attraktivität dieser zentralen Lage. Die effizient aufgeteilte Bürofläche wird über ein großzügiges und repräsentatives Entrée mit zwei Personenaufzügen erschlossen. Zur hochwertigen Ausstattung der Räumlichkeiten zählen bodentiefe Fenster, Sonnenschutzverglasung, Beleuchtungssysteme, ein hochwertiger Teppichfußboden, Bodentanks, eine Pantry sowie getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgen in Absprache mit dem zukünftigen Mieter. Pkw-Stellplätze können auf Anfrage im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_24905.pdf', null, 'filemaker', '24905') on conflict (id) do nothing;
