insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25166')::uuid, md5('building-kohlentwiete-14-22761')::uuid, '25166', 'dachgeschoss-highlight-mit-grosszuegiger-terrasse-25166', 'Dachgeschoss-Highlight mit großzügiger Terrasse', 'Das Dachgeschoss der modernen Gewerbeimmobilie, die 2002 errichtet und 2015 erweitert wurde, präsentiert sich als hochwertig ausgestattete Fläche mit vielseitigen …', 'Das Dachgeschoss der modernen Gewerbeimmobilie, die 2002 errichtet und 2015 erweitert wurde, präsentiert sich als hochwertig ausgestattete Fläche mit vielseitigen Nutzungsmöglichkeiten. Aktuell wird diese als Eventfläche genutzt und überzeugt durch eine moderne Ausstattung, darunter eine Projektionsfläche, LED-Ambientebeleuchtung, elektrische Rollos sowie eine Klimaanlage. Eine flexible Raumgestaltung ist durch eine dreiteilige Faltwand möglich.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25166-1')::uuid, md5('property-25166')::uuid, 'Mietfläche', 278, 18, null, 'filemaker', '25166-1') on conflict (id) do nothing;
