insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24890')::uuid, md5('building-grosse-elbstrasse-38-22767')::uuid, '24890', 'individuelle-bueroflaeche-mit-blick-auf-elbe-und-fischauktionshalle-24890', 'Individuelle Bürofläche mit Blick auf Elbe und Fischauktionshalle', 'Das moderne Büro- und Geschäftsgebäude ist unmittelbar am Wasser gelegen und bietet einen traumhaften Blick auf den Hamburger Fischmarkt und die Elbe. Die Anbindung an den ÖPNV …', 'Das moderne Büro- und Geschäftsgebäude ist unmittelbar am Wasser gelegen und bietet einen traumhaften Blick auf den Hamburger Fischmarkt und die Elbe. Die Anbindung an den ÖPNV ist durch die S-Bahnstation Königstraße gegeben. Das lebendige Umfeld ist geprägt von einem vielfältigen gastronomischen Angebot. Neben erstklassiger internationaler Küche trifft man auch auf Fischhändler und urige Hafenkneipen. Die Fläche ist über einen Personenaufzug zu erreichen. Zur Ausstattung gehören Betondecken, elektrischer außenliegender Sonnenschutz, Kat-7-Verkabelung, sowie Bereiche mit Teppich- und Vinylboden. PKW-Stellplätze können bei Bedarf in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_24890.pdf', null, 'filemaker', '24890') on conflict (id) do nothing;
