insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25222')::uuid, md5('building-schlossstrasse-6-22041')::uuid, '25222', 'bueroflaeche-in-bester-lage-von-wandsbek-25222', 'Bürofläche in bester Lage von Wandsbek', 'Das Bürogebäude befindet sich in bester Lage von Wandsbek direkt gegenüber vom Einkaufszentrum Quarree. Nach nur wenigen Metern erreicht man den Verkehrsknotenpunkt Wandsbek Markt …', 'Das Bürogebäude befindet sich in bester Lage von Wandsbek direkt gegenüber vom Einkaufszentrum Quarree. Nach nur wenigen Metern erreicht man den Verkehrsknotenpunkt Wandsbek Markt mit Anschluss an diverse Bus-, U- und S-Bahnlinien. Das direkte Umfeld als auch das Quarree sorgen für einen schnellen Zugang zu allen Geschäften des täglichen Bedarfs sowie vielen Cafés und Restaurants.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25222-1')::uuid, md5('property-25222')::uuid, 'Mietfläche', 281, 16, null, 'filemaker', '25222-1') on conflict (id) do nothing;
