insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24316')::uuid, md5('building-deelboege-19-22297')::uuid, '24316', 'moderner-bueroneubau-nahe-eppendorfer-muehlenteich-24316', 'Moderner Büroneubau nahe Eppendorfer Mühlenteich', 'Der hochmoderne Leed-Gold zertifizierte Office Campus Flow befindet sich zwischen dem Alsterlauf und dem Eppendorfer Mühlenteich in zentraler Lage von Eppendorf. Die nur wenige …', 'Der hochmoderne Leed-Gold zertifizierte Office Campus Flow befindet sich zwischen dem Alsterlauf und dem Eppendorfer Mühlenteich in zentraler Lage von Eppendorf. Die nur wenige Fußminuten entfernte U-Bahnstation Lattenkamp sowie eine Bushaltestelle direkt am Objekt  sorgen für eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Auch die Autobahnanschlüsse zur A7, A23, A24 und A1 sowie der Hamburger Flughafen sind nach wenigen Fahrminuten erreicht. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24316-1')::uuid, md5('property-24316')::uuid, 'Mietfläche', 282, 18.5, null, 'filemaker', '24316-1') on conflict (id) do nothing;
