insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18274')::uuid, md5('building-niedernstrasse-10-20095')::uuid, '18274', 'hochwertige-bueroflaeche-im-kontorhausviertel-18274', 'Hochwertige Bürofläche im Kontorhausviertel', 'Das charmante, zum Teil unter Denkmalschutz stehende, ehemalige Postgebäude befindet sich in bester Innenstadtlage unmittelbar gegenüber des Chilehauses. Die U-Bahnstation Meßberg …', 'Das charmante, zum Teil unter Denkmalschutz stehende, ehemalige Postgebäude befindet sich in bester Innenstadtlage unmittelbar gegenüber des Chilehauses. Die U-Bahnstation Meßberg ist fußläufig erreichbar. Besonders der Eingangsbereich bietet schöne Stilelemente. Die Bürofläche kann nach den individuellen Wünschen des Mieters ausgebaut werden und bietet einen einmaligen Blick über die Speicherstadt und die neue Hafencity. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-18274-1')::uuid, md5('property-18274')::uuid, 'Mietfläche', 283, 28.5, null, 'filemaker', '18274-1') on conflict (id) do nothing;
